// Package stack runs the Stack of a Chat or a Run: a compose project of the
// Project's compose.yml and compose.afk.yml from the base branch, plus an
// override generated by afk. Its service `afk` is the Sandbox (ADR-0013).
package stack

import (
	"bytes"
	"context"
	"errors"
	"fmt"
	"io"
	"maps"
	"os"
	"os/exec"
	"path/filepath"
	"regexp"
	"slices"
	"strings"
	"syscall"
	"time"

	"golang.org/x/term"
)

const (
	sandboxService = "afk"
	setupService   = "afk-setup"
	podmanBinary   = "podman"

	// terminateWait is how long a terminated Attach gets to restore the terminal.
	terminateWait = 10 * time.Second

	// Kinds of Stack; they name its state directory and compose project.
	Chat Kind = "chat"
	Run  Kind = "run"

	// factoryScope names the cache volumes all Runs of a Project share.
	factoryScope = "factory"
)

var (
	namePattern = regexp.MustCompile(`^[a-z0-9]([a-z0-9-]{0,38}[a-z0-9])?$`)
	// commitPattern is a full SHA-1 or SHA-256: never an option or a ref name.
	commitPattern = regexp.MustCompile(`^[0-9a-f]{40}([0-9a-f]{24})?$`)
)

// Kind is what a Stack is for.
type Kind string

// Options describe a Stack. Project, Kind and Name determine its compose
// project and its place in the state directory.
type Options struct {
	Repo     string // the user's repository: the source of the exports
	Commit   string // full SHA of the base branch commit to export
	Project  string // [a-z0-9-], e.g. owner-name
	Kind     Kind
	Name     string // Chat name or ticket-N
	StateDir string // ~/.local/state/afk, absolute
	// Env goes to the Sandbox through a file of mode 0600, never argv.
	Env    map[string]string
	Mounts []Mount
	// Expose publishes ports: service -> [address:]host_port:container_port.
	Expose map[string][]string
	// Out gets the progress of builds and of afk-setup (nil: discarded).
	Out io.Writer
}

// Stack is the compose project of one Chat or Run.
type Stack struct {
	opts     Options
	dir      string // <state>/<project>/<kind>s/<name>
	hostHome string
	socket   string // the rootless podman socket

	protected []string // Dockerfiles of the services with build:, set by Up
}

// New validates opts. It touches nothing: Up creates the Stack, and Down and
// Remove work on the state an earlier process left.
func New(opts Options) (s *Stack, err error) {
	if !commitPattern.MatchString(opts.Commit) {
		err = fmt.Errorf("commit %q: want a full SHA", opts.Commit)
		return
	}
	for key, value := range opts.Env {
		// compose interpolates env files: $ in a value would be expanded.
		if key == "" || strings.ContainsAny(key, "=\n") || strings.ContainsAny(value, "\n$") {
			err = fmt.Errorf("env %q: no newline, $ or = allowed", key)
			return
		}
	}
	if s, err = Open(opts.StateDir, opts.Project, opts.Kind, opts.Name); err != nil {
		return
	}
	for _, m := range opts.Mounts {
		if err = rejectSocketMounts(s.socket, map[string][]string{"mount": {m.Source}}); err != nil {
			return
		}
	}
	s.opts = opts
	return
}

// Open is the Stack of an earlier process, for Down and Remove, which work on
// its state alone: no repository, commit or mounts. Up needs New.
func Open(stateDir, project string, kind Kind, name string) (s *Stack, err error) {
	if !namePattern.MatchString(project) {
		err = fmt.Errorf("project %q: want [a-z0-9-], up to 40 characters", project)
		return
	}
	if !namePattern.MatchString(name) {
		err = fmt.Errorf("%s name %q: want [a-z0-9-], up to 40 characters", kind, name)
		return
	}
	if kind != Chat && kind != Run {
		err = fmt.Errorf("unknown kind %q", kind)
		return
	}
	if !filepath.IsAbs(stateDir) {
		err = fmt.Errorf("state directory %q: want an absolute path", stateDir)
		return
	}
	runtimeDir := os.Getenv("XDG_RUNTIME_DIR")
	if runtimeDir == "" {
		err = errors.New("XDG_RUNTIME_DIR is not set: no rootless podman socket")
		return
	}
	home, err := os.UserHomeDir()
	if err != nil {
		return
	}
	s = &Stack{
		opts:     Options{Project: project, Kind: kind, Name: name, StateDir: stateDir},
		dir:      Dir(stateDir, project, kind, name),
		hostHome: home,
		socket:   filepath.Join(runtimeDir, "podman", "podman.sock"),
	}
	return
}

// --- state ---

var projectNamePattern = regexp.MustCompile(`^[A-Za-z0-9_][A-Za-z0-9._-]*$`)

// ProjectName derives the Project's directory name in the state directory
// from [forge].repo ("graf0/dfmx" becomes "graf0-dfmx").
func ProjectName(repo string) (name string, err error) {
	name = strings.ReplaceAll(repo, "/", "-")
	if !projectNamePattern.MatchString(name) || strings.Contains(name, "..") {
		err = fmt.Errorf("cannot derive a project name from forge.repo %q", repo)
		name = ""
	}
	return
}

// DefaultStateDir is ~/.local/state/afk.
func DefaultStateDir() (dir string, err error) {
	home, err := os.UserHomeDir()
	if err != nil {
		err = fmt.Errorf("finding home directory: %w", err)
		return
	}
	dir = filepath.Join(home, ".local", "state", "afk")
	return
}

// Dir is the state directory of a Stack: the one that stays after Down and is
// the only record of the Stack (ADR-0015).
func Dir(stateDir, project string, kind Kind, name string) (dir string) {
	return filepath.Join(stateDir, project, string(kind)+"s", name)
}

// List returns the names of the Stacks of kind that have state, sorted: the
// directories under the Project's state, nothing else keeps a record.
func List(stateDir, project string, kind Kind) (names []string, err error) {
	entries, err := os.ReadDir(filepath.Dir(Dir(stateDir, project, kind, "x")))
	if errors.Is(err, os.ErrNotExist) {
		err = nil
		return
	}
	if err != nil {
		return
	}
	for _, entry := range entries {
		if entry.IsDir() && namePattern.MatchString(entry.Name()) {
			names = append(names, entry.Name())
		}
	}
	return
}

// Tree is the directory the Sandbox works in, at the same path on the host
// and in the Sandbox. The clone of a Chat or Run lives here.
func (s *Stack) Tree() (path string) { return TreeIn(s.dir) }

// TreeIn is the tree of the Stack whose state directory (Dir) is dir.
func TreeIn(dir string) (path string) { return filepath.Join(dir, "repo") }

// Home is the host side of the Agent's $HOME.
func (s *Stack) Home() (path string) { return filepath.Join(s.dir, "home") }

// ProjectName is the name of the compose project: it tells Chats and Runs
// apart, and both from other Projects.
func (s *Stack) ProjectName() (name string) {
	// "_" cannot appear in a name: no two Stacks share a compose project.
	return fmt.Sprintf("afk_%s_%s_%s", s.opts.Project, s.opts.Kind, s.opts.Name)
}

// cacheScope prefixes the names of cache volumes: one per Chat, one shared by
// all Runs of the Project. compose.afk.yml reads it as ${AFK_CACHE}.
func (s *Stack) cacheScope() (prefix string) {
	if s.opts.Kind == Run {
		return fmt.Sprintf("afk_%s_%s", s.opts.Project, factoryScope)
	}
	return s.ProjectName()
}

func (s *Stack) exportDir() (path string)    { return filepath.Join(s.dir, "export") }
func (s *Stack) overridePath() (path string) { return filepath.Join(s.dir, "override.yml") }
func (s *Stack) envPath() (path string)      { return filepath.Join(s.dir, "agent.env") }
func (s *Stack) setupMarker() (path string)  { return filepath.Join(s.dir, "setup.done") }

// --- Up ---

// Up starts the Stack from the base branch: it exports the compose files,
// builds the images that lack a tag for their definition, starts the
// services, but not afk-setup (Setup). A failure leaves what
// started; Down cleans up.
func (s *Stack) Up(ctx context.Context) (err error) {
	for _, dir := range []string{s.dir, s.Tree(), s.Home()} {
		if err = os.MkdirAll(dir, 0o755); err != nil {
			return
		}
	}
	if err = export(ctx, s.opts.Repo, s.opts.Commit, s.exportDir()); err != nil {
		return
	}
	if err = rejectExternalFiles(s.exportDir()); err != nil {
		return
	}
	if err = s.writeEnv(); err != nil {
		return
	}
	defer func() { err = errors.Join(err, s.removeEnv()) }()
	services, err := s.config(ctx)
	if err != nil {
		return
	}
	sources := map[string][]string{}
	for name, service := range services {
		for _, volume := range service.Volumes {
			if volume.Type == "bind" {
				sources[name] = append(sources[name], volume.Source)
			}
		}
	}
	if err = rejectSocketMounts(s.socket, sources); err != nil {
		return
	}
	if _, ok := services[sandboxService]; !ok {
		err = fmt.Errorf("%s defines no service %q", composeAfkFile, sandboxService)
		return
	}
	images := map[string]string{}
	for name, service := range services {
		if service.Build == nil {
			continue
		}
		if images[name], err = s.tag(ctx, name, service.Build); err != nil {
			return
		}
	}
	if s.protected, err = protectedDockerfiles(s.exportDir(), services); err != nil {
		return
	}
	if err = s.writeOverride(images, slices.Sorted(maps.Keys(services))); err != nil {
		return
	}
	if err = s.build(ctx, images); err != nil {
		return
	}
	var start []string
	for _, name := range slices.Sorted(maps.Keys(services)) {
		if name != setupService {
			start = append(start, name)
		}
	}
	if err = s.compose(ctx, true, nil, append([]string{"up", "--detach", "--no-build"}, start...)...); err != nil {
		return
	}
	return
}

// tag is the image tag of service from the base commit: the git tree of its
// build context decides, so no file of the working tree matters.
func (s *Stack) tag(ctx context.Context, service string, build map[string]any) (tag string, err error) {
	dir, _ := build["context"].(string)
	if dir == "" {
		err = fmt.Errorf("service %s: build without a local context is not supported", service)
		return
	}
	contextRel, err := relativeTo(s.exportDir(), dir)
	if err != nil {
		err = fmt.Errorf("service %s: build context: %w", service, err)
		return
	}
	contextTree, err := s.revision(ctx, contextRel)
	if err != nil {
		err = fmt.Errorf("service %s: build context: %w", service, err)
		return
	}
	var dockerfileBlob string
	rel, inline, err := dockerfilePath(s.exportDir(), build)
	if err != nil {
		err = fmt.Errorf("service %s: dockerfile: %w", service, err)
		return
	}
	// Inside the context its tree covers the Dockerfile; outside it does not.
	if _, inContext := relativeTo(dir, filepath.Join(s.exportDir(), rel)); !inline && inContext != nil {
		if dockerfileBlob, err = s.revision(ctx, rel); err != nil {
			err = fmt.Errorf("service %s: dockerfile: %w", service, err)
			return
		}
	}
	tag, err = imageTag(s.opts.Project, service, s.exportDir(), build, contextTree, dockerfileBlob)
	return
}

// revision is the git object id of path (relative to the repository root, "."
// for the root) at the base commit.
func (s *Stack) revision(ctx context.Context, path string) (id string, err error) {
	spec := s.opts.Commit + ":"
	if path != "." {
		spec += filepath.ToSlash(path)
	}
	out, err := exec.CommandContext(ctx, "git", "-C", s.opts.Repo, "rev-parse", "--verify", "--end-of-options", spec).Output()
	if err != nil {
		err = fmt.Errorf("%s is not on the base branch: %w", path, err)
		return
	}
	id = strings.TrimSpace(string(out))
	return
}

// build builds the images that have no tag yet.
func (s *Stack) build(ctx context.Context, images map[string]string) (err error) {
	var missing []string
	for _, name := range slices.Sorted(maps.Keys(images)) {
		if exec.CommandContext(ctx, podmanBinary, "image", "exists", images[name]).Run() != nil {
			missing = append(missing, name)
		}
	}
	if len(missing) == 0 {
		return
	}
	s.say("building images: %s", strings.Join(missing, ", "))
	err = s.compose(ctx, true, nil, append([]string{"build"}, missing...)...)
	return
}

// Setup runs afk-setup, once per Stack: the marker lives in its state, so a
// second call, also after Down and Up, does nothing. It is a call of its own,
// after Up, so that the caller can put the clone in the tree first: afk-setup
// sees it. Without a service afk-setup it only sets the marker.
func (s *Stack) Setup(ctx context.Context) (err error) {
	if _, err = os.Stat(s.setupMarker()); err == nil {
		return
	}
	services, err := s.config(ctx)
	if err != nil {
		return
	}
	if _, ok := services[setupService]; ok {
		s.say("running %s", setupService)
		if err = s.compose(ctx, true, nil, "run", "--rm", "--no-TTY", setupService); err != nil {
			err = fmt.Errorf("%s: %w", setupService, err)
			return
		}
	}
	err = os.WriteFile(s.setupMarker(), nil, 0o644)
	return
}

func (s *Stack) removeEnv() (err error) {
	if err = os.Remove(s.envPath()); errors.Is(err, os.ErrNotExist) {
		err = nil
	}
	return
}

func (s *Stack) writeEnv() (err error) {
	var buf bytes.Buffer
	for _, key := range slices.Sorted(maps.Keys(s.opts.Env)) {
		fmt.Fprintf(&buf, "%s=%s\n", key, s.opts.Env[key])
	}
	// A file that exists is rewritten: it may hold an older token.
	if err = os.Remove(s.envPath()); err != nil && !errors.Is(err, os.ErrNotExist) {
		return
	}
	err = os.WriteFile(s.envPath(), buf.Bytes(), 0o600)
	return
}

func (s *Stack) writeOverride(images map[string]string, services []string) (err error) {
	// Every service starts without ports: those of compose.yml are not ours to publish.
	ports := map[string][]string{}
	for _, name := range services {
		ports[name] = nil
	}
	for service, specs := range s.opts.Expose {
		if _, ok := ports[service]; !ok {
			err = fmt.Errorf("expose: the Stack has no service %q", service)
			return
		}
		for _, spec := range specs {
			var port string
			if port, err = ParseExpose(spec); err != nil {
				err = fmt.Errorf("service %s: %w", service, err)
				return
			}
			if strings.HasPrefix(port, "0.0.0.0:") {
				s.say("warning: %s is published on all addresses (LAN)", spec)
			}
			ports[service] = append(ports[service], port)
		}
	}
	data, err := overrideFile(overrideInput{
		Tree: s.Tree(), Home: s.Home(), HostHome: s.hostHome, EnvFile: s.envPath(),
		Mounts: s.opts.Mounts, Ports: ports, Images: images,
	})
	if err != nil {
		return
	}
	err = os.WriteFile(s.overridePath(), data, 0o644)
	return
}

// --- Exec, Down, Remove ---

// Exec runs command with bash in the tree, in the Sandbox. Its stdout goes
// to stdout; an error carries the tail of its stderr.
func (s *Stack) Exec(ctx context.Context, command string, stdout io.Writer) (err error) {
	err = s.compose(ctx, true, stdout, "exec", "--no-TTY", "--workdir", s.Tree(), sandboxService, "bash", "-c", command)
	return
}

// Attach runs command with bash in the tree, in the Sandbox, on the caller's
// streams: with a terminal for in it gets a pty, so an interactive program
// works. A failure of the command comes back as its exit status.
func (s *Stack) Attach(ctx context.Context, command string, in *os.File, out, errOut io.Writer) (err error) {
	args := []string{"exec"}
	if !term.IsTerminal(int(in.Fd())) {
		args = append(args, "--no-TTY")
	}
	args = append(args, "--workdir", s.Tree(), sandboxService, "bash", "-c", command)
	cmd, err := s.command(ctx, true, args...)
	if err != nil {
		return
	}
	cmd.Stdin, cmd.Stdout, cmd.Stderr = in, out, errOut
	// SIGTERM, not the SIGKILL of exec.CommandContext: docker-compose puts the
	// terminal in raw mode and restores it on the way out.
	cmd.Cancel = func() error { return cmd.Process.Signal(syscall.SIGTERM) }
	cmd.WaitDelay = terminateWait
	if err = cmd.Run(); err != nil {
		err = fmt.Errorf("%s exec: %w", composeBinary, err)
	}
	return
}

// Container is the name of the Sandbox's container, for the one who wants to
// `podman exec` into it by hand.
func (s *Stack) Container(ctx context.Context) (name string, err error) {
	out, err := exec.CommandContext(ctx, podmanBinary, "ps", "--format", "{{.Names}}",
		"--filter", "label=com.docker.compose.project="+s.ProjectName(),
		"--filter", "label=com.docker.compose.service="+sandboxService).Output()
	if err != nil {
		err = fmt.Errorf("finding the Sandbox container: %w", err)
		return
	}
	names := strings.Fields(string(out))
	if len(names) == 0 {
		err = errors.New("the Sandbox container is not running")
		return
	}
	name = names[0]
	return
}

// Down removes the containers and the network of the Stack. Volumes and the
// state stay.
func (s *Stack) Down(ctx context.Context) (err error) {
	if _, err = os.Stat(s.dir); errors.Is(err, os.ErrNotExist) {
		err = nil // never started
		return
	}
	if err = s.removeEnv(); err != nil {
		return
	}
	// Anonymous volumes (masks) would outlive their containers: rm drops them.
	if _, statErr := os.Stat(s.exportDir()); statErr == nil {
		if err = s.compose(ctx, true, nil, "rm", "--stop", "--force", "--volumes"); err != nil {
			return
		}
	}
	err = s.compose(ctx, true, nil, "down", "--remove-orphans")
	return
}

// Remove does Down, then deletes the volumes of the Stack (not the cache
// all Runs share) and its state: tree, home and exports.
func (s *Stack) Remove(ctx context.Context) (err error) {
	if err = s.Down(ctx); err != nil {
		return
	}
	out, err := exec.CommandContext(ctx, podmanBinary, "volume", "ls", "--quiet",
		"--filter", "label=com.docker.compose.project="+s.ProjectName()).Output()
	if err != nil {
		err = fmt.Errorf("listing volumes: %w", err)
		return
	}
	for _, volume := range strings.Fields(string(out)) {
		if s.opts.Kind == Run && strings.HasPrefix(volume, s.cacheScope()+"-") {
			continue
		}
		if removeOut, removeErr := exec.CommandContext(ctx, podmanBinary, "volume", "rm", "--force", volume).CombinedOutput(); removeErr != nil {
			err = fmt.Errorf("removing volume %s: %w: %s", volume, removeErr, strings.TrimSpace(string(removeOut)))
			return
		}
	}
	if err = os.RemoveAll(s.dir); err != nil {
		// Mount points of nested volumes can belong to a subuid.
		if out, unshareErr := exec.CommandContext(ctx, podmanBinary, "unshare", "rm", "-rf", s.dir).CombinedOutput(); unshareErr != nil {
			err = fmt.Errorf("removing %s: %w: %s", s.dir, unshareErr, strings.TrimSpace(string(out)))
			return
		}
		err = nil
	}
	return
}

func (s *Stack) say(format string, args ...any) {
	if s.opts.Out != nil {
		_, _ = fmt.Fprintf(s.opts.Out, "= stack: "+format+"\n", args...)
	}
}
